<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';use RetroWEB\Infrastructure\Persistence\DeviceSubmissionRepository;use RetroWEB\Domain\Profile\ProfileDetector;$root=dirname(__DIR__);$repo=new DeviceSubmissionRepository($root.'/var/data/device-submissions-v2.sqlite');$command=$argv[1]??'list';if($command==='list'){foreach($repo->pending()as$row)echo $row['id']."\t".$row['device']."\t".$row['browser']."\t".$row['user_agent']."\t".$row['confirmations']."\n";exit;}if(in_array($command,['approve','reject'],true)&&isset($argv[2])){$id=(int)$argv[2];$row=$repo->submission($id);if($row===null)throw new OutOfBoundsException('Submission not found');if($command==='approve'){$detection=(new ProfileDetector(require $root.'/config/profiles/signatures.php'))->detect($row['user_agent']);$repo->moderate($id,'approved',$detection->profileId,$detection->status);}else$repo->moderate($id,'rejected');echo ucfirst($command)."d submission ".$id.".\n";exit;}fwrite(STDERR,"Usage: php bin/device-submissions.php list|approve ID|reject ID\n");exit(2);
